def cc(n):
    s = ''
    while n != 0:
        s = str(n % 5) +  s
        n //= 5
    return s

def f(n):
    s = cc(n)
    if s[-1] == '0':
        s = s.replace('1','*').replace('4','1').replace('*','4')
        s = '33' + s
    else:
        s += '42'
        s = '3' + s[1:]
    return int(s,5)

